using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD vectorization.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;
        int i = 0;

        // Use 256-bit vectors (8 floats) for the main loop
        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count)
        {
            var vProduct0 = Vector256<float>.One;
            var vProduct1 = Vector256<float>.One;
            var vProduct2 = Vector256<float>.One;
            var vProduct3 = Vector256<float>.One;

            int limit = length - Vector256<float>.Count * 4 + 1;
            // Unrolled loop: 4 accumulators to hide multiply latency
            for (; i < limit; i += Vector256<float>.Count * 4)
            {
                vProduct0 *= Vector256.LoadUnsafe(ref start, (nuint)i);
                vProduct1 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count));
                vProduct2 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count * 2));
                vProduct3 *= Vector256.LoadUnsafe(ref start, (nuint)(i + Vector256<float>.Count * 3));
            }

            // Handle remaining full vectors
            for (; i <= length - Vector256<float>.Count; i += Vector256<float>.Count)
                vProduct0 *= Vector256.LoadUnsafe(ref start, (nuint)i);

            // Combine accumulators and reduce
            vProduct0 = vProduct0 * vProduct1 * vProduct2 * vProduct3;
            var v128 = vProduct0.GetLower() * vProduct0.GetUpper();
            float product = v128[0] * v128[1] * v128[2] * v128[3];

            // Scalar tail
            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count)
        {
            var vProduct0 = Vector128<float>.One;
            var vProduct1 = Vector128<float>.One;

            int limit = length - Vector128<float>.Count * 2 + 1;
            for (; i < limit; i += Vector128<float>.Count * 2)
            {
                vProduct0 *= Vector128.LoadUnsafe(ref start, (nuint)i);
                vProduct1 *= Vector128.LoadUnsafe(ref start, (nuint)(i + Vector128<float>.Count));
            }

            for (; i <= length - Vector128<float>.Count; i += Vector128<float>.Count)
                vProduct0 *= Vector128.LoadUnsafe(ref start, (nuint)i);

            vProduct0 *= vProduct1;
            float product = vProduct0[0] * vProduct0[1] * vProduct0[2] * vProduct0[3];

            for (; i < length; i++)
                product *= Unsafe.Add(ref start, i);

            return product;
        }

        // Scalar fallback with 4x unroll
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int scalarLimit = length - 3;
        for (; i < scalarLimit; i += 4)
        {
            p0 *= Unsafe.Add(ref start, i);
            p1 *= Unsafe.Add(ref start, i + 1);
            p2 *= Unsafe.Add(ref start, i + 2);
            p3 *= Unsafe.Add(ref start, i + 3);
        }
        float result = p0 * p1 * p2 * p3;
        for (; i < length; i++)
            result *= Unsafe.Add(ref start, i);

        return result;
    }
}

